import { test } from '@playwright/test';
import { Wopee } from '@wopee-io/wopee.pw';

const wopee = new Wopee();

test.beforeAll(async () => {
  await wopee.startSuite(`Angular visual ${new Date().toISOString().slice(0, 16)}`);
});
test.beforeEach(async ({}, testInfo) => {
  await wopee.startScenario(testInfo.title, testInfo);
});
test.afterEach(async () => {
  await wopee.stopScenario();
});

test('Settings and edit profile dialog', async ({ page }) => {
  await page.goto('/settings');
  await page.getByRole('heading', { name: 'Settings' }).waitFor();
  await wopee.trackFullPage({ page, stepName: 'Settings page' });

  await page.getByRole('button', { name: 'Edit profile' }).click();
  // Material dialogs render in the CDK overlay container, outside the component.
  await page.getByRole('dialog').waitFor();
  await wopee.trackViewport({ page, stepName: 'Edit profile dialog' });
});

