    cy.get('mat-dialog-container').should('be.visible');
    cy.get('mat-dialog-container').wopeeTrack({ stepName: 'Order details dialog' });
  });
});

import { browser, $ } from '@wdio/globals';

describe('Angular dashboard', () => {
  before(async () => {
    await browser.startSuite(`Angular WDIO ${new Date().toISOString().slice(0, 16)}`);
  });

  it('shows the dashboard and the filter menu', async () => {
    await browser.startScenario('Dashboard: overview and filter menu');

    await browser.url('http://localhost:4200/dashboard');
    await $('h1=Dashboard').waitForDisplayed();
    await browser.execute(async () => {
      await document.fonts.ready;
    });
    const overview = await browser.trackFullPageScreen({ stepName: 'Dashboard' });
    console.log('Dashboard:', overview.screenshotValidationResult?.status);

    await $('button[aria-label="Filter"]').click();
    await $('.cdk-overlay-pane').waitForDisplayed();
    await browser.trackScreen({ stepName: 'Filter menu open' });

    await browser.stopScenario();
  });
});

import { test, expect } from '@playwright/test';
import { Wopee } from '@wopee-io/wopee.pw';

const wopee = new Wopee();

test.beforeAll(async () => {
  await wopee.startSuite(`React visual ${new Date().toISOString().slice(0, 16)}`);
});
test.beforeEach(async ({}, testInfo) => {
  await wopee.startScenario(testInfo.title, testInfo);
});
test.afterEach(async () => {
  await wopee.stopScenario();
});

test('Cart and checkout', async ({ page }) => {
  await page.goto('/cart');
  // Wait for real data, not the Suspense skeleton.
  await page.getByRole('table', { name: 'Cart items' }).waitFor();
  await wopee.trackFullPage({ page, stepName: 'Cart' });

  await page.getByRole('button', { name: 'Checkout' }).click();
  const form = page.getByRole('form', { name: 'Shipping address' });
  await form.waitFor();
  const result = await wopee.trackElement({ locator: form, stepName: 'Shipping form' });
  expect(result?.status).not.toBe('unresolved');
});

