import { test } from '@playwright/test';
import { Wopee } from '@wopee-io/wopee.pw';

// CI sets BASE_URL to the preview deploy, WOPEE_BRANCH_NAME to the PR branch
// and WOPEE_BASELINE_BRANCH_NAME=main.
test.use({ baseURL: process.env.BASE_URL ?? 'http://localhost:3000' });

const wopee = new Wopee();

test.beforeAll(async () => {
  await wopee.startSuite(`Next.js preview ${process.env.GITHUB_RUN_NUMBER ?? 'local'}`);
});
test.beforeEach(async ({}, testInfo) => {
  await wopee.startScenario(testInfo.title, testInfo);
});
test.afterEach(async () => {
  await wopee.stopScenario();
});

test('Pricing page', async ({ page }) => {
  await page.goto('/pricing');
  // Wait for the streamed content behind loading.tsx, then fonts and images.
  await page.getByRole('heading', { name: 'Pricing' }).waitFor();
  await page.evaluate(async () => {
    await Promise.all([
      ...[...document.fonts].map((font) => font.load()),
      ...[...document.images].map((img) => img.decode().catch(() => {})),
    ]);
  });
  await wopee.trackFullPage({ page, stepName: 'Pricing' });
});

