import { test } from '@playwright/test';
import { Wopee } from '@wopee-io/wopee.pw';

const wopee = new Wopee();
const locales = ['en', 'de'];

test.beforeAll(async () => {
  await wopee.startSuite(`Vue visual ${new Date().toISOString().slice(0, 16)}`);
});
test.beforeEach(async ({}, testInfo) => {
  await wopee.startScenario(testInfo.title, testInfo);
});
test.afterEach(async () => {
  await wopee.stopScenario();
});

for (const locale of locales) {
  test(`Account page (${locale})`, async ({ page }) => {
    await page.goto(`/${locale}/account`);
    await page.getByRole('main').getByRole('heading', { level: 1 }).waitFor();
    // customTags is part of the baseline identity: one baseline per locale.
    await wopee.trackFullPage({ page, stepName: 'Account', customTags: locale });
  });
}

