for (const size of [{ width: 1280, height: 800 }, { width: 390, height: 844 }]) {
  test(`Products at ${size.width}px`, async ({ page }) => {
    await page.setViewportSize(size);
    await page.goto('/products');
    // The list renders after hydration; wait for it, not the server HTML.
    await page.getByRole('list', { name: 'Products' }).getByRole('listitem').first().waitFor();
    await wopee.trackFullPage({
      page,
      stepName: 'Products',
      viewport: `${size.width}x${size.height}`,
    });
  });
}
